827	/****************************************************************************
828	 * Private Functions - Hardware Transmit
829	 ****************************************************************************/
830	
831	static int hw_transmit(struct sg2000_eth_priv_s *priv,
832	                       const uint8_t *data, int len)
833	{
834	  unsigned int idx = priv->tx_cur;
835	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
836	  irqstate_t flags;
837	
838	  /* Check if the ring is full */
839	
840	  if (desc->des0 & DESC_OWN)
841	    {
842	      return -EBUSY;
843	    }
844	
845	  /* Copy data to DMA TX buffer */
846	
847	  memcpy(priv->tx_buf[idx], data, len);
848	
849	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
850	  desc->des1 = len;
851	
852	  /* OWN | First Segment | Last Segment | Interrupt on Completion */
853	
854	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
855	               (len & RX_DESC_FL_MASK);
856	
857	  flags = up_irq_save();
858	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
859	
860	  /* Memory barrier: ensure descriptor is visible to DMA engine */
861	
862	  __asm__ volatile ("fence w,w" ::: "memory");
863	
864	  tx_doorbell(priv);
865	  up_irq_restore(flags);
866	
867	  return 0;
868	}
