/****************************************************************************
 * Private Functions - D-Cache Coherency for DMA (T-Head C906)
 *
 * C906 provides custom dcache instructions for physical-address-based
 * cache maintenance.  We use dcache.cpa (write-back) and dcache.cipa
 * (write-back + invalidate) to keep DMA buffers coherent.
 *
 * Cache line size = 64 bytes.
 ****************************************************************************/

#define DCACHE_LINE_SIZE  64

/* dcache.cpa — clean (write-back) cache line for physical address.
 * Keeps the cache copy; lets DMA see CPU-written data.
 */

static void dma_wb_range(uintptr_t start, uintptr_t end)
{
  uintptr_t i = start & ~(DCACHE_LINE_SIZE - 1);
  for (; i < end; i += DCACHE_LINE_SIZE)
    {
      __asm__ volatile (".long 0x0295000b"  /* dcache.cpa a0 */
                        :: "r"(i) : "memory");
    }

  __asm__ volatile ("fence rw,rw" ::: "memory");
}

/* dcache.cipa — clean + invalidate cache line for physical address.
 * Discards the cache copy; ensures CPU reads fresh DMA-written data.
 */

static void dma_wbinv_range(uintptr_t start, uintptr_t end)
{
  uintptr_t i = start & ~(DCACHE_LINE_SIZE - 1);
  for (; i < end; i += DCACHE_LINE_SIZE)
    {
      __asm__ volatile (".long 0x02b5000b"  /* dcache.cipa a0 */
                        :: "r"(i) : "memory");
    }

  __asm__ volatile ("fence rw,rw" ::: "memory");
}

/* DMA sync helpers */

static void dma_sync_for_device(uintptr_t addr, size_t len)
{
  /* CPU wrote data → write-back so DMA can read it */

  dma_wb_range(addr, addr + len);
}

static void dma_sync_for_cpu(uintptr_t addr, size_t len)
{
  /* DMA wrote data → write-back + invalidate so CPU reads fresh data */

  dma_wbinv_range(addr, addr + len);
}

