static int dma_soft_reset(uintptr_t gmac_base)
{
  uint32_t val;
  int timeout = 100000;

  val = getreg32(gmac_base + DMA_BUS_MODE);
  syslog(LOG_INFO, "sg2000_eth: DMA reset begin bus_mode=0x%08" PRIX32
         "\n", val);
  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);

  do
    {
      val = getreg32(gmac_base + DMA_BUS_MODE);
      if (!(val & DMA_SFT_RESET))
        {
          return 0;
        }

      up_udelay(10);
    }
  while (--timeout > 0);

  syslog(LOG_ERR, "sg2000_eth: DMA reset timeout bus_mode=0x%08" PRIX32
         " hw_feature0=0x%08" PRIX32 "\n",
         getreg32(gmac_base + DMA_BUS_MODE),
         getreg32(gmac_base + GMAC_HW_FEATURE0));
  return -1;
}

