static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
{
  uintptr_t base = priv->gmac_base;
  uint32_t v;

  /* Configure GMAC_CONTROL based on PHY negotiation results */

  v = GMAC_CORE_INIT;
  if (priv->speed == 100)
    {
      v |= GMAC_CONTROL_FES;  /* 100Mbps (when PS=1) */
    }

  if (priv->duplex)
    {
      v |= GMAC_CONTROL_DM;   /* Full duplex */
    }

  putreg32(v, base + GMAC_CONTROL);

  /* Frame filter: accept all multicast + broadcast + promiscuous */

  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
           base + GMAC_FRAME_FILTER);

  /* Enable MAC TX and RX (set TE=bit3, RE=bit2) */

  v = getreg32(base + GMAC_CONTROL);
  putreg32(v | GMAC_CONTROL_TE | GMAC_CONTROL_RE, base + GMAC_CONTROL);

  /* Start TX DMA: DMA_CONTROL (CSR6) bit 13 = ST */

  v = getreg32(base + DMA_CONTROL);
  putreg32(v | DMA_CONTROL_ST, base + DMA_CONTROL);

  /* Start RX DMA: DMA_CONTROL (CSR6) bit 1 = SR */

  v = getreg32(base + DMA_CONTROL);
  putreg32(v | DMA_CONTROL_SR, base + DMA_CONTROL);
}

