static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
{
  FAR struct sg2000_eth_priv_s *priv =
      (FAR struct sg2000_eth_priv_s *)dev;
  uint32_t v;

  up_disable_irq(priv->irq);

  /* Stop TX DMA */

  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
  putreg32(v & ~DMA_TX_ST,
           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);

  /* Stop RX DMA */

  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
  putreg32(v & ~DMA_RX_SR,
           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);

  /* Disable MAC TX/RX */

  v = getreg32(priv->gmac_base + GMAC_CONFIG);
  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
           priv->gmac_base + GMAC_CONFIG);

  netdev_lower_carrier_off(dev);

  ninfo("netdriver_ifdown: interface down\n");

  return OK;
}

